def daily_topk(score, k=15):
    d = tx.assign(score=score)
    top = d.sort_values("score", ascending=False).groupby("day").head(k)
    caught = top["is_fraud"].sum()
    return {"precision@k": caught / len(top), "recall": caught / tx["is_fraud"].sum(),
            "fraud_rs_captured_%": 100 * top.loc[top["is_fraud"] == 1, "amount"].sum() / tx.loc[tx["is_fraud"] == 1, "amount"].sum()}
rule = (tx["amount"] > 25000).astype(int) + ((tx["night"] == 1) & (tx["new_device"] == 1)).astype(int)
rule_score = rule + tx["amount"] / tx["amount"].max()
results = {"rules": daily_topk(rule_score)}
print(pd.DataFrame(results).T.round(3))
